        // Cancel any pending timer
        if (timer !== null) {
            clearTimeout(timer);
            timer = null;
        }

        // Record the time of this call
        lastCallTime = Date.now();

        // Schedule the function to run after waitMs
        timer = setTimeout(() => {
            // Only call if this is still the most recent call
            if (lastCallTime === Date.now()) {
